  ?z rdf:type brick:Zone .
  ?z ref:hasName ?pname .
  OPTIONAL { ?ts ref:hasTimeseriesId ?tid ; ref:isPointOf ?z }
  OPTIONAL { ?ts ref:hasTimeseriesId ?tid ; brick:hasPoint ?z }
} LIMIT 200

