import csv
from collections import defaultdict
vals=defaultdict(dict)
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        vals[row['timeseries_id']][row['timestamp']]=float(row['value'])

def occupied(ts):
    from datetime import datetime
    d=datetime.fromisoformat(ts)
    return d.weekday()<5 and 9<=d.hour<17

def stats(tid, before=True):
    sel=[]
    for ts,v in vals[tid].items():
        if not occupied(ts): continue
        if before: 
            if '2018-01'<=ts<='2018-06-10': sel.append(v)
        else:
            if '2018-06-10'<=ts<='2018-12-31': sel.append(v)
    if sel: return sum(sel)/len(sel), len(sel)
    return None,None

